def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    my_last, opp_last = history[-1]

    opp_d = 0
    my_d = 0
    tolerated = 0
    ret_d = 0
    unprov_d = 0
    punish_fail = 0

    for i in range(n):
        m, o = history[i]
        if o == 'D':
            opp_d += 1
        if m == 'D':
            my_d += 1
            if o == 'C':
                tolerated += 1
        if i > 0:
            pm, po = history[i - 1]
            if o == 'D':
                if pm == 'C':
                    unprov_d += 1
                else:
                    ret_d += 1
            if po == 'D' and pm == 'C' and m == 'D' and o == 'D':
                punish_fail += 1

    opp_rate = opp_d / n
    opp_c_rate = 1.0 - opp_rate

    opp_d10 = 0
    for _, o in history[-10:]:
        if o == 'D':
            opp_d10 += 1

    opp_d5 = 0
    for _, o in history[-5:]:
        if o == 'D':
            opp_d5 += 1

    opp_streak_d = 0
    for _, o in reversed(history):
        if o == 'D':
            opp_streak_d += 1
        else:
            break

    dd_streak = 0
    for m, o in reversed(history):
        if m == 'D' and o == 'D':
            dd_streak += 1
        else:
            break

    chronic = False
    if n >= 6 and opp_d == n:
        chronic = True
    if n >= 12 and opp_rate > 0.5:
        chronic = True
    if n >= 12 and opp_d10 >= 8:
        chronic = True
    if n >= 15 and unprov_d >= 5 and opp_rate > 0.2:
        chronic = True
    if n >= 12 and punish_fail >= 3 and opp_rate > 0.22:
        chronic = True
    if n >= 15 and opp_streak_d >= 7 and opp_rate > 0.15:
        chronic = True
    if n >= 12 and opp_d5 >= 4 and opp_rate > 0.3:
        chronic = True

    if chronic:
        return 'D'

    if opp_last == 'D':
        if my_last == 'D':
            if opp_streak_d >= 3 and (opp_rate > 0.25 or unprov_d >= 2 or punish_fail >= 2):
                return 'D'
            if dd_streak >= 2 and opp_c_rate > 0.45 and unprov_d <= 4:
                return 'C'
            if dd_streak == 1 and opp_streak_d <= 2 and opp_c_rate > 0.6:
                return 'D'
            if opp_rate < 0.25 and opp_streak_d <= 2:
                return 'C'
            return 'D'

        if opp_streak_d >= 3:
            return 'D'
        if n >= 2 and history[-2][0] == 'D' and unprov_d <= 3 and opp_rate < 0.35:
            return 'C'
        if n >= 2 and history[-2] == ('D', 'C') and unprov_d <= 3:
            return 'C'
        if opp_rate < 0.1 and opp_streak_d == 1 and rng.random() < 0.2:
            return 'C'
        return 'D'

    if my_last == 'D':
        if n >= 2 and history[-2] == ('C', 'D'):
            return 'C'
        if opp_d == 0:
            if tolerated >= 2 or n >= 50:
                return 'D'
            return 'D' if rng.random() < 0.5 else 'C'
        if ret_d == 0 and tolerated >= 1 and opp_rate < 0.1:
            return 'D'
        if opp_rate < 0.18 and tolerated >= 2 and rng.random() < 0.35:
            return 'D'
        if opp_rate < 0.25 and ret_d <= 1 and tolerated >= 3 and rng.random() < 0.2:
            return 'D'
        if n >= 90 and opp_rate < 0.15 and tolerated >= 1:
            return 'D'
        return 'C'

    if opp_d == 0:
        if n < 10:
            return 'C'
        p = 0.1
        if n >= 20:
            p = 0.25
        if n >= 40:
            p = 0.45
        if n >= 70:
            p = 0.7
        if rng.random() < p:
            return 'D'
        return 'C'

    if opp_rate < 0.15 and my_d < 3 and rng.random() < 0.08:
        return 'D'
    if opp_rate < 0.08 and n >= 50 and rng.random() < 0.15:
        return 'D'

    return 'C'
